/* Экраны изолированного UI-прототипа; рабочий сервер не используется. */
(function () {
  if (!window.Prototype?.requested) return;
  const P = Prototype, S = window.Screens;
  const { html, useState, useEffect } = window.htmPreact;
  const I = (name, size = 20) => html`<${UI.Icon} name=${name} size=${size} />`;
  const money = (n) => U.money(n || 0);
  const run = (fn, done) => { try { const result = fn(); if (done) done(result); return result; } catch (e) { UI.toast(e.message, 'err'); return undefined; } };
  const go = (tab, extra = {}) => UI.go('kassaView', { tab, ...extra });
  const newest = (xs) => [...xs].sort((a, b) => (b.postedAt || b.at).localeCompare(a.postedAt || a.at));
  const form = (title, Body, props = {}, size = 'workspace') => UI.modal({ title, size, body: (mid) => html`<${Body} ...${props} mid=${mid} />` });
  const Top = ({ title, children, back = 'Касса', onBack }) => html`<header class="workspace-header"><button type="button" class="btn" onClick=${onBack || (() => UI.go('kassaHome'))}>${I('chevron-left', 18)}${back}</button><h1>${title}</h1><div class="workspace-header-actions">${children}</div></header>`;
  const Page = ({ title, children, actions, back, onBack }) => html`<div class="workspace-page"><${Top} title=${title} back=${back} onBack=${onBack}>${actions}<//><div class="workspace-content">${children}</div></div>`;
  const Search = ({ value, onChange, placeholder = 'Поиск', label = 'Поиск' }) => html`<div class="workspace-search">${I('search')}<input type="search" aria-label=${label} value=${value} placeholder=${placeholder} onInput=${(e) => onChange(e.target.value)} /></div>`;
  const Empty = ({ text = 'Ничего не найдено' }) => html`<div class="workspace-empty">${text}</div>`;
  const Status = ({ text, tone = '' }) => html`<span class="workspace-status ${tone}">${text}</span>`;
  const Grid = ({ head, rows, cells, onOpen, numeric = [], empty, label = 'Список' }) => html`<div class="workspace-table-wrap"><table class="workspace-table" aria-label=${label}><thead><tr>${head.map((h, i) => html`<th class=${numeric.includes(i) ? 'num' : ''}>${h}</th>`)}</tr></thead><tbody>${rows.map((r) => html`<tr key=${r.id} tabindex=${onOpen ? 0 : undefined} class=${onOpen ? 'clickable' : ''} onClick=${() => onOpen && onOpen(r)} onKeyDown=${(e) => { if (onOpen && ['Enter', ' '].includes(e.key)) { e.preventDefault(); onOpen(r); } }}>${cells(r).map((c, i) => html`<td class=${numeric.includes(i) ? 'num' : ''}>${c}</td>`)}</tr>`)}</tbody></table>${!rows.length ? html`<${Empty} text=${empty} />` : null}</div>`;
  const Stat = ({ title, value, onClick }) => html`<button type="button" class="workspace-stat" disabled=${!onClick} onClick=${onClick}><span>${title}</span><strong>${value}</strong></button>`;
  const Stats = ({ from, to }) => { const s = P.summary(from, to); return html`<div class="workspace-stats"><${Stat} title="Продаж" value=${s.count} /><${Stat} title="Выручка" value=${`${money(s.revenue)} сом`} /><${Stat} title="Получено денег" value=${`${money(s.received)} сом`} /><${Stat} title="Продано в долг" value=${`${money(s.givenDebt)} сом`} /><//>`; };
  const Tabs = ({ items, value, onChange }) => html`<nav class="workspace-tabs" aria-label="Разделы">${items.map((t) => html`<button type="button" key=${t.k} aria-pressed=${value === t.k} class=${value === t.k ? 'selected' : ''} onClick=${() => onChange(t.k)}>${t.icon ? I(t.icon) : null}${t.t}</button>`)}</nav>`;
  const Period = ({ from, to, setFrom, setTo }) => html`<div class="workspace-period"><button type="button" class="btn" onClick=${() => { setFrom(P.day()); setTo(P.day()); }}>Сегодня</button><button type="button" class="btn" onClick=${() => { setFrom(''); setTo(''); }}>Все даты</button><input type="date" aria-label="С даты" value=${from} onInput=${(e) => setFrom(e.target.value)} /><span>—</span><input type="date" aria-label="По дату" value=${to} onInput=${(e) => setTo(e.target.value)} /></div>`;
  const openDoc = (ref) => UI.go('kassaDocView', ref);
  const methods = (p) => {
    const source = p.src ? E.doc(p.src) : null;
    return p.method ? E.PAY_LABELS[p.method] : Object.keys(source?.payMethods || {}).filter((k) => source.payMethods[k] > 0).map((k) => E.PAY_LABELS[k]).join(' + ') || '—';
  };
  const saleStatus = (s) => s.status === 'cancelled' ? 'Отменён' : s.pending ? 'Ждёт отправки' : P.saleDebt(s) > 0 ? (s.paid > 0 ? 'Частично оплачен' : 'В долг') : E.S.returns.some((r) => r.saleId === s.id && r.status === 'posted') ? 'Есть возврат' : 'Оплачен';

  function Login() {
    const [login, setLogin] = useState('demo'), [password, setPassword] = useState('demo'), [error, setError] = useState('');
    return html`<div class="workspace-login"><h1>ХозУчёт</h1><${Status} text="Тестовый режим" /><form onSubmit=${(e) => { e.preventDefault(); try { P.login(login, password); } catch (x) { setError(x.message); } }}><label>Логин<input aria-label="Логин" autocomplete="username" value=${login} onInput=${(e) => setLogin(e.target.value)} /></label><label>Пароль<input aria-label="Пароль" type="password" autocomplete="current-password" value=${password} onInput=${(e) => setPassword(e.target.value)} /></label>${error ? html`<p class="workspace-error" role="alert">${error}</p>` : null}<button class="btn pri" type="submit">Войти</button></form></div>`;
  }
  UI.PrototypeShell = ({ children }) => {
    const [, force] = useState(0);
    useEffect(() => { const f = () => force((n) => n + 1); E.listeners.push(f); return () => { E.listeners = E.listeners.filter((x) => x !== f); }; }, []);
    const waiting = P.jobs.filter((j) => ['pending', 'error'].includes(j.state)).length;
    return html`<div class="workspace-shell"><div class="workspace-bar"><button type="button" class="workspace-brand" onClick=${() => UI.go('kassaHome')}>ХозУчёт</button><${Status} text="Тестовый режим" tone="test" /><span class="workspace-bar-sp"></span>${P.authenticated ? html`<button type="button" onClick=${() => UI.go('kassaDay')}>${I('bar-chart', 18)}Итоги</button><button type="button" onClick=${() => UI.go('kassaCatalog')}>${I('package', 18)}Каталог</button><button type="button" onClick=${() => form('Тестовые операции', Transport)}> ${I('settings', 18)}${waiting ? `В очереди: ${waiting}` : 'Операции'}</button><span class="workspace-connection ${P.online ? '' : 'offline'}">${P.online ? 'Сохранено' : 'Нет связи'}</span><button type="button" onClick=${P.logout}>Выйти</button>` : null}</div>${P.authenticated ? children : html`<${Login} />`}</div>`;
  };
  S.kassaHome = () => {
    const summary = P.summary(), drafts = P.drafts();
    const tile = (icon, label, action) => html`<button type="button" class="kassa-tile" onClick=${action}>${I(icon, 34)}<span>${label}</span></button>`;
    return html`<div class="workspace-home"><div class="workspace-home-heading"><h1>Касса</h1><button type="button" class="btn" onClick=${() => UI.go('kassaDay')}>${U.fmtDate(E.now())}${I('bar-chart', 18)}</button></div><${Stats} from=${P.day()} to=${P.day()} /><div class="workspace-home-actions">${tile('shopping-cart', 'Продажа', () => UI.kassaStart('sale'))}${tile('package-plus', 'Новый товар', () => form('Новый товар', ProductEditor, {}, 'workspace wide'))}${tile('clipboard-list', 'Заказ', () => UI.kassaStart('order'))}${tile('eye', 'Просмотр', () => go('sales'))}</div><div class="workspace-balances"><button onClick=${() => go('people', { debtFilter: 'recv' })}><span>Нам должны</span><b>${money(summary.receivable)} сом</b></button><button onClick=${() => go('people', { debtFilter: 'pay' })}><span>Мы должны</span><b>${money(summary.payable)} сом</b></button></div>${drafts.length ? html`<div class="workspace-resume">${I('clipboard-list', 24)}<div><b>Отложенные чеки</b><span>${drafts.length} · ${money(drafts.reduce((n, d) => n + E.calcLines(d).total, 0))} сом</span></div><button class="btn" onClick=${() => go('drafts')}>Все чеки</button><button class="btn pri" onClick=${() => UI.go('kassaSale', { id: drafts[0].id })}>Продолжить</button></div>` : null}</div>`;
  };
  S.kassaDay = () => {
    const [from, setFrom] = useState(P.day()), [to, setTo] = useState(P.day());
    const sales = E.S.sales.filter((s) => s.status === 'posted' && P.inPeriod(s.postedAt, from, to));
    const map = new Map();
    sales.forEach((s) => { const id = s.cp || 'retail'; if (!map.has(id)) map.set(id, { id, name: E.cpName(s.cp), count: 0, amount: 0, debt: 0 }); const r = map.get(id); r.count++; r.amount = U.r2(r.amount + s.total); r.debt = U.r2(r.debt + s.total - s.paid); });
    const summary = P.summary(from, to);
    return html`<${Page} title="Итоги" actions=${html`<button class="btn" onClick=${() => UI.print(html`<${DaySheet} from=${from} to=${to} />`)}>${I('printer')}Печать</button>`}><${Period} from=${from} to=${to} setFrom=${setFrom} setTo=${setTo} />${from && to && from > to ? html`<div class="workspace-error" role="alert">Начальная дата позже конечной</div>` : null}<${Stats} from=${from} to=${to} /><h2 class="workspace-section-title">Кому продали</h2><${Grid} head=${['Покупатель', 'Чеков', 'Продажи, сом', 'Продано в долг, сом']} rows=${[...map.values()]} numeric=${[1,2,3]} cells=${(r) => [r.name, r.count, money(r.amount), money(r.debt)]} empty="За этот период продаж нет" /><div class="workspace-report-lines"><div><span>Возвраты</span><b>${money(summary.returns)} сом</b></div><div><span>Выдано денег</span><b>${money(summary.paidOut)} сом</b></div></div><//>`;
  };
  S.kassaView = ({ tab: initial = 'sales', debtFilter: initialDebt = 'all' }) => {
    const [tab, setTab] = useState(initial), [q, setQ] = useState(''), [from, setFrom] = useState(initial === 'sales' || initial === 'payments' ? P.day() : ''), [to, setTo] = useState(initial === 'sales' || initial === 'payments' ? P.day() : ''), [debtFilter, setDebtFilter] = useState(initialDebt);
    const change = (value) => { setTab(value); setQ(''); setFrom(value === 'sales' || value === 'payments' ? P.day() : ''); setTo(value === 'sales' || value === 'payments' ? P.day() : ''); };
    const hit = (d) => U.match(q, d.no, E.cpName(d.cp), d.comment, d.author) && P.inPeriod(d.postedAt || d.at, from, to);
    const tabs = [{ k:'sales',t:'Продажи',icon:'shopping-cart' },{ k:'orders',t:'Заказы',icon:'clipboard-list' },{ k:'people',t:'Люди и долги',icon:'users' },{ k:'payments',t:'Платежи',icon:'wallet' },{ k:'returns',t:'Возвраты',icon:'arrow-left' },{ k:'drafts',t:'Черновики',icon:'save' }];
    let content;
    if (tab === 'sales') content = html`<${Grid} label="Продажи" head=${['Чек', 'Покупатель', 'Дата', 'Сумма, сом', 'Долг, сом', 'Статус']} rows=${newest(E.S.sales.filter((s) => s.status !== 'draft' && hit(s)))} numeric=${[3,4]} onOpen=${(s) => openDoc(E.ref(s))} cells=${(s) => [s.no, E.cpName(s.cp), U.fmtDT(s.postedAt), html`<b>${money(s.total)}</b>`, money(P.saleDebt(s)), html`<${Status} text=${saleStatus(s)} tone=${s.status === 'cancelled' ? '' : s.pending || P.saleDebt(s) ? 'warn' : 'ok'} />`]} empty="Продаж не найдено" />`;
    else if (tab === 'people') {
      const people = E.S.cps.map((c) => ({ ...c, ...E.balance(c.id) })).filter((c) => U.match(q, c.name, c.phone) && (debtFilter === 'all' || c[debtFilter] > 0)).sort((a,b) => b.recv+b.pay-a.recv-a.pay);
      content = html`<${Tabs} value=${debtFilter} onChange=${setDebtFilter} items=${[{k:'all',t:'Все'}, {k:'recv',t:'Нам должны'}, {k:'pay',t:'Мы должны'}]} /><${Grid} head=${['Человек', 'Телефон', 'Нам должны, сом', 'Мы должны, сом']} rows=${people} numeric=${[2,3]} onOpen=${(c) => UI.go('kassaPerson', {id:c.id})} cells=${(c) => [html`<b>${c.name}</b>`, c.phone || '—', html`<b class=${c.recv ? 'workspace-debt-recv' : 'muted'}>${money(c.recv)}</b>`, html`<b class=${c.pay ? 'workspace-debt-pay' : 'muted'}>${money(c.pay)}</b>`]} empty="Никого не найдено" />`;
    } else if (tab === 'orders') content = html`<${OrderBoard} orders=${E.S.orders.filter((o) => o.lines.length && hit(o))} />`;
    else if (tab === 'payments') content = html`<${Grid} head=${['Операция', 'Человек', 'Дата', 'Способ', 'Сумма, сом']} rows=${newest(E.S.payments.filter((p) => p.status === 'posted' && hit(p)))} numeric=${[4]} onOpen=${(p) => openDoc(E.ref(p))} cells=${(p) => [html`<div class="workspace-cell"><b>${p.dir === 'in' ? 'Получено' : 'Выдано'}</b><small>${p.no}</small></div>`, E.cpName(p.cp), U.fmtDT(p.postedAt), methods(p), html`<b>${money(p.amount)}</b>`]} empty="Платежей не найдено" />`;
    else if (tab === 'returns') content = html`<${Grid} head=${['Возврат', 'Покупатель', 'Дата', 'Сумма, сом']} rows=${newest(E.S.returns.filter((r) => r.status === 'posted' && hit(r)))} numeric=${[3]} onOpen=${(r) => openDoc(E.ref(r))} cells=${(r) => [r.no, E.cpName(r.cp), U.fmtDT(r.postedAt), money(r.amount)]} empty="Возвратов не найдено" />`;
    else content = html`<${Grid} head=${['Чек', 'Покупатель', 'Создан', 'Товаров', 'Сумма, сом']} rows=${P.drafts().filter(hit)} numeric=${[3,4]} onOpen=${(d) => UI.go('kassaSale',{id:d.id})} cells=${(d) => [d.no,E.cpName(d.cp),U.fmtDT(d.at),E.documentProductGroups(d).length,money(E.calcLines(d).total)]} empty="Отложенных чеков нет" />`;
    return html`<${Page} title="Просмотр" actions=${tab === 'people' ? html`<button class="btn" onClick=${() => form('Записать долг', DebtEditor)}>${I('wallet')}Записать долг</button><button class="btn pri" onClick=${() => form('Новый человек', PersonEditor)}>${I('plus')}Добавить</button>` : null}><${Tabs} items=${tabs} value=${tab} onChange=${change} /><div class="workspace-toolbar"><${Search} value=${q} onChange=${setQ} placeholder=${tab === 'people' ? 'Имя или телефон' : 'Номер или имя'} />${!['people','drafts'].includes(tab) ? html`<${Period} from=${from} to=${to} setFrom=${setFrom} setTo=${setTo} />` : null}</div>${from && to && from > to ? html`<p class="workspace-error" role="alert">Начальная дата позже конечной</p>` : null}${content}<//>`;
  };

  function PersonEditor({ mid, id, initial = '', onSave }) {
    const c = id ? E.cp(id) : null;
    const [name, setName] = useState(c?.name || initial), [phone, setPhone] = useState(c?.phone || ''), [note, setNote] = useState(c?.note || ''), [error, setError] = useState('');
    return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { const person = E.saveCp({ name, phone, note }, id); UI.close(mid); if (onSave) onSave(person); else UI.go('kassaPerson', { id: person.id }); } catch (x) { setError(x.message); } }}><label>Имя<input class="in" aria-label="Имя" value=${name} autofocus onInput=${(e) => setName(e.target.value)} /></label><label>Телефон<input class="in" aria-label="Телефон" type="tel" value=${phone} onInput=${(e) => setPhone(e.target.value)} /></label><label>Комментарий<textarea class="in" value=${note} onInput=${(e) => setNote(e.target.value)} /></label>${error ? html`<p class="workspace-error" role="alert">${error}</p>` : null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Отмена</button><button type="submit" class="btn pri" disabled=${!name.trim()}>Сохранить</button></div></form>`;
  }
  function PersonPicker({ mid, title, allowNone = false, onPick }) {
    const [q, setQ] = useState('');
    const choose = (id) => { UI.close(mid); onPick(id); };
    const rows = E.S.cps.filter((c) => c.active !== false && U.match(q, c.name, c.phone));
    return html`<div class="workspace-picker"><div class="workspace-toolbar"><${Search} value=${q} onChange=${setQ} placeholder="Имя или телефон" /><button type="button" class="btn" aria-label="Добавить человека" onClick=${() => form('Новый человек', PersonEditor, { initial: q, onSave: (c) => choose(c.id) })}>${I('plus')}</button></div>${allowNone ? html`<button type="button" class="workspace-person-row" onClick=${() => choose(null)}><b>Розничный покупатель</b></button>` : null}<div class="workspace-picker-list">${rows.map((c) => { const b = E.balance(c.id); return html`<button type="button" class="workspace-person-row" key=${c.id} onClick=${() => choose(c.id)}><div><b>${c.name}</b>${c.phone ? html`<small>${c.phone}</small>` : null}</div><div class="workspace-person-amounts">${b.recv ? html`<span>Нам ${money(b.recv)}</span>` : null}${b.pay ? html`<span>Мы ${money(b.pay)}</span>` : null}</div></button>`; })}${!rows.length ? html`<${Empty} />` : null}</div></div>`;
  }
  UI.pickCustomer = (options) => form(options.title || 'Покупатель', PersonPicker, options);
  UI.cpQuick = (initial, onSave) => form('Новый человек', PersonEditor, { initial, onSave });

  function PriceTerms({ mid, product, line, onSave }) {
    const [price, setPrice] = useState(line.price), [discount, setDiscount] = useState(E.calcLines({ lines:[{...line, qty:Math.max(1,line.qty || 0)}], dVal:0 }).lines[0].lineDisc);
    const [borrowed, setBorrowed] = useState(!!line.neighbor);
    const [neighbor, setNeighbor] = useState(line.neighbor?.cp || null);
    const [borrowQty, setBorrowQty] = useState(line.neighbor?.qty || Math.max(1,line.qty || 0));
    const [borrowPrice, setBorrowPrice] = useState(line.neighbor?.price || 0);
    const calculation = E.calcLines({ lines: [{ qty: Math.max(1, line.qty || 0), price, dVal: discount, dType: 'сум' }], dType: '%', dVal: 0 });
    const borrowing = borrowed ? {cp:neighbor,qty:borrowQty,price:borrowPrice} : null;
    const borrowingErrors = E.neighborErrors({qty:Math.max(1,line.qty || 0),neighbor:borrowing},product.unit);
    const valid = U.isNum(price) && price >= 0 && U.isNum(discount) && discount >= 0 && !calculation.lines[0].errs.length && !borrowingErrors.length;
    return html`<form class="workspace-form" onSubmit=${(e) => {
      e.preventDefault(); if (!valid) return;
      onSave({price,dVal:discount,dType:'сум',neighbor:borrowing}); UI.close(mid);
    }}>
      <div class="workspace-form-product"><b>${product.name}</b><span>${product.variantName}</span></div>
      <div class="workspace-terms-grid">
        <label>Цена продажи, сом<${UI.Num} cls="in workspace-big-input" aria-label="Цена" value=${price} onChange=${setPrice} /></label>
        <label>Скидка, сом<${UI.Num} cls="in workspace-big-input" aria-label="Скидка" value=${discount} onChange=${setDiscount} /></label>
      </div>
      <label class="workspace-checkbox workspace-borrow-toggle"><input type="checkbox" checked=${borrowed} onChange=${(e) => setBorrowed(e.target.checked)} />Взяли у соседа</label>
      ${borrowed ? html`<section class="workspace-borrow-fields">
        <button type="button" class="workspace-select-person" onClick=${() => UI.pickCustomer({title:'Сосед',onPick:setNeighbor})}>${I('users')}<b>${neighbor ? E.cpName(neighbor) : 'Выбрать соседа'}</b>${I('chevron-left',16)}</button>
        <div class="workspace-terms-grid">
          <label>Взяли, ${product.unit}<${UI.Num} cls="in workspace-big-input" aria-label="Количество у соседа" value=${borrowQty} onChange=${setBorrowQty} /></label>
          <label>Цена соседа за 1 ${product.unit}, сом<${UI.Num} cls="in workspace-big-input" aria-label="Цена соседа" value=${borrowPrice} onChange=${setBorrowPrice} /></label>
        </div>
        <div class="workspace-total-line"><span>Будем должны соседу</span><b>${money(U.isNum(borrowQty) && U.isNum(borrowPrice) ? U.r2(borrowQty*borrowPrice) : 0)} сом</b></div>
        ${borrowingErrors.length ? html`<p class="workspace-error" role="alert">${borrowingErrors[0].msg}</p>` : null}
      </section>` : null}
      <div class="workspace-total-line"><span>Сумма продажи</span><b>${money(calculation.total)} сом</b></div>
      ${!valid && !borrowingErrors.length ? html`<p class="workspace-error" role="alert">Проверьте цену и скидку</p>` : null}
      <div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Отмена</button><button type="submit" class="btn pri" disabled=${!valid}>Сохранить</button></div>
    </form>`;
  }
  UI.priceTerms = (product, line, onSave) => form('Цена и условия', PriceTerms, { product, line, onSave });

  function DebtEditor({ mid, cp: initialCp = null }) {
    const [cp, setCp] = useState(initialCp), [dir, setDir] = useState('recv'), [amount, setAmount] = useState(0), [comment, setComment] = useState(''), [error, setError] = useState('');
    return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { P.recordDebt(cp, dir, amount, comment); UI.close(mid); UI.go('kassaPerson', { id: cp }); } catch (x) { setError(x.message); } }}><button type="button" class="workspace-select-person" onClick=${() => UI.pickCustomer({ title: 'Человек', onPick: setCp })}>${I('users')}<b>${cp ? E.cpName(cp) : 'Выбрать человека'}</b></button><${Tabs} value=${dir} onChange=${setDir} items=${[{k:'recv',t:'Нам должны'}, {k:'pay',t:'Мы должны'}]} /><label>Сумма, сом<${UI.Num} cls="in workspace-big-input" aria-label="Сумма долга" value=${amount} onChange=${setAmount} /></label><label>Основание<textarea class="in" aria-label="Основание долга" value=${comment} onInput=${(e) => setComment(e.target.value)} /></label>${error ? html`<p class="workspace-error" role="alert">${error}</p>` : null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Отмена</button><button type="submit" class="btn pri" disabled=${!cp || !U.isNum(amount) || amount <= 0}>Записать</button></div></form>`;
  }
  function DebtPayment({ mid, cp, dir }) {
    const total = E.balance(cp)[dir];
    const [amount, setAmount] = useState(total), [method, setMethod] = useState('cash'), [error, setError] = useState('');
    const valid = U.isNum(amount) && amount > 0 && amount <= total;
    return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { P.settle(cp, dir, amount, method); UI.close(mid); UI.toast('Оплата сохранена', 'ok'); } catch (x) { setError(x.message); } }}><div class="workspace-form-product"><b>${E.cpName(cp)}</b><span>${dir === 'recv' ? 'Нам должны' : 'Мы должны'} ${money(total)} сом</span></div><label>Сумма, сом<${UI.Num} cls="in workspace-big-input" aria-label="Сумма погашения" value=${amount} onChange=${setAmount} /></label><${Tabs} value=${method} onChange=${setMethod} items=${[{k:'cash',t:'Наличные'}, {k:'mbank',t:'МБанк'}]} /><div class="workspace-total-line"><span>Останется долг</span><b>${money(Math.max(0, total - (U.isNum(amount) ? amount : 0)))} сом</b></div>${error || !valid ? html`<p class="workspace-error" role="alert">${error || 'Сумма должна быть больше нуля и не больше долга'}</p>` : null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Отмена</button><button type="submit" class="btn pri" disabled=${!valid}>${dir === 'recv' ? 'Принять оплату' : 'Выдать деньги'}</button></div></form>`;
  }
  function ConfirmReason({ mid, onConfirm, label = 'Подтвердить' }) {
    const [reason, setReason] = useState(''), [error, setError] = useState('');
    return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { onConfirm(reason.trim()); UI.close(mid); } catch (x) { setError(x.message); } }}><label>Причина<textarea class="in" aria-label="Причина" autofocus value=${reason} onInput=${(e) => setReason(e.target.value)} /></label>${error ? html`<p class="workspace-error" role="alert">${error}</p>` : null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Назад</button><button type="submit" class="btn danger" disabled=${!reason.trim()}>${label}</button></div></form>`;
  }

  function docData(ref) {
    const d = E.doc(ref);
    if (!d) return null;
    let doc = d, calc = ['sale','order'].includes(ref.t) ? E.calcLines(d) : {lines:[],total:d.amount || 0}, source = null;
    if (ref.t === 'debt' && d.sourceSaleId) source = E.doc({t:'sale',id:d.sourceSaleId});
    if (ref.t === 'ret') {
      source = E.doc({ t:'sale', id:d.saleId });
      const lines = d.lines.filter((l) => l.qty > 0).map((l) => { const original = source.lines[l.li]; return { ...l, pid:original.pid, price:original.amount/original.qty, productSnapshot:original.productSnapshot || E.product(original.pid) }; });
      doc = { ...d, lines };
      calc = { total:d.amount, lines:lines.map((l) => ({ amount:l.amount, gross:l.amount, disc:0 })) };
    }
    const groups = ['sale','order','ret'].includes(ref.t) ? E.documentProductGroups(doc, calc) : [];
    return { d, doc, calc, source, groups, total:groups.length ? calc.total : d.amount || 0 };
  }
  function DocumentLines({ data, worker = false }) {
    return html`<div class="workspace-table-wrap"><table class="workspace-table workspace-document-lines"><thead><tr><th>Товар / размер</th><th class="num">Количество</th>${worker ? html`<th>Собрано</th>` : html`<th class="num">Цена, сом</th><th class="num">Сумма, сом</th>`}</tr></thead>${data.groups.map((g) => html`<tbody key=${g.key}><tr class="workspace-product-heading"><th colspan=${worker ? 3 : 4}>${g.name}</th></tr>${g.items.map((item) => html`<tr><td>${item.product.variantName || 'Основной'}${item.discount > 0 ? html`<small class="workspace-line-discount">Скидка −${money(item.discount)} сом</small>` : null}</td><td class="num">${U.qtyU(item.line.qty,item.product.unit)}</td>${worker ? html`<td><span class="workspace-print-check"></span></td>` : html`<td class="num">${money(item.line.price)}</td><td class="num"><b>${money(item.amount)}</b></td>`}</tr>`)}</tbody>`)}</table></div>`;
  }
  function NeighborSummary({ doc }) {
    const rows = (doc.lines || []).filter((l) => l.neighbor);
    if (!rows.length) return null;
    return html`<section class="workspace-borrow-summary"><h2>Взяли у соседей</h2>${rows.map((l) => {
      const p = l.productSnapshot || E.product(l.pid), n = l.neighbor;
      const note = l.neighborDebtId && E.doc({t:'debt',id:l.neighborDebtId});
      const debt = note && E.S.debts.find((d) => d.ref.t === 'debt' && d.ref.id === note.id && !d.cancelled);
      const amount = U.r2(n.qty*n.price);
      return html`<div class="workspace-borrow-row"><div><button type="button" class="workspace-person-link" onClick=${() => UI.go('kassaPerson',{id:n.cp})}><b>${E.cpName(n.cp)}</b></button><span>${E.productLabel(p)}</span><small>${U.qtyU(n.qty,p.unit)} × ${money(n.price)} сом</small></div><div><b>${money(amount)} сом</b>${note ? html`<small>${note.status === 'cancelled' ? 'Отменено' : `Осталось: ${money(debt ? E.debtRem(debt) : 0)} сом`}</small><button type="button" class="btn" onClick=${() => openDoc(E.ref(note))}>${note.no}</button>` : null}</div></div>`;
    })}</section>`;
  }
  function DocumentSheet({ documentRef: ref, worker = false }) {
    const data = docData(ref); if (!data) return null;
    const d = data.d, returned = ref.t === 'sale' ? E.S.returns.filter((r) => r.saleId === d.id && r.status === 'posted').reduce((n,r) => n+r.amount,0) : 0;
    return html`<article class="sheet workspace-print-sheet"><header><span>ХозУчёт</span><h1>${worker ? 'Лист сборки' : ref.t === 'ret' ? 'Возврат' : ref.t === 'order' ? 'Заказ' : 'Накладная'} № ${d.no}</h1></header><div class="workspace-print-meta"><div><span>Покупатель</span><b>${E.cpName(d.cp)}</b></div><div><span>Дата</span><b>${U.fmtDT(d.postedAt || d.at)}</b></div></div>${d.comment ? html`<p>${d.comment}</p>` : null}${data.source ? html`<p>По чеку ${data.source.no}</p>` : null}${d.status === 'cancelled' ? html`<p class="workspace-error">Документ отменён</p>` : null}<${DocumentLines} data=${data} worker=${worker} />${worker ? null : html`<div class="workspace-print-totals"><div><span>Итого</span><b>${money(data.total)} сом</b></div>${ref.t === 'sale' ? html`${returned ? html`<div><span>Возвращено</span><b>${money(returned)} сом</b></div>` : null}<div><span>Оплачено при продаже</span><b>${money(d.paid)} сом</b></div><div><span>Долг сейчас</span><b>${money(P.saleDebt(d))} сом</b></div>` : ref.t === 'ret' ? html`<div><span>Возвращено деньгами</span><b>${money(d.refundNow)} сом</b></div><div><span>Уменьшение долга</span><b>${money(d.toDebt)} сом</b></div>` : null}</div>`}<footer><span>${worker ? 'Собрал' : 'Отпустил'} ____________________</span><span>${worker ? 'Проверил' : 'Получил'} ____________________</span></footer></article>`;
  }
  UI.workspacePrint = (ref, worker = false) => UI.modal({ title:worker ? 'Лист сборки' : 'Накладная', size:'wide', body:() => html`<div class="workspace-print-preview"><${DocumentSheet} documentRef=${ref} worker=${worker} /></div>`, foot:() => html`<button type="button" class="btn pri" onClick=${() => UI.print(html`<${DocumentSheet} documentRef=${ref} worker=${worker} />`)}>${I('printer')}Печать</button>` });
  function DaySheet({ from, to }) {
    const summary = P.summary(from,to), sales = E.S.sales.filter((s) => s.status === 'posted' && P.inPeriod(s.postedAt,from,to));
    return html`<article class="sheet workspace-print-sheet"><header><span>ХозУчёт</span><h1>Продажи за период</h1><p>${from || 'Начало'} — ${to || 'Сегодня'}</p></header><${Grid} head=${['Чек','Покупатель','Сумма, сом','В долг, сом']} rows=${sales} numeric=${[2,3]} cells=${(s) => [s.no,E.cpName(s.cp),money(s.total),money(s.total-s.paid)]} empty="Нет продаж" /><div class="workspace-print-totals"><div><span>Продаж</span><b>${summary.count}</b></div><div><span>Выручка</span><b>${money(summary.revenue)} сом</b></div><div><span>Получено денег</span><b>${money(summary.received)} сом</b></div><div><span>Продано в долг</span><b>${money(summary.givenDebt)} сом</b></div><div><span>Возвраты</span><b>${money(summary.returns)} сом</b></div></div></article>`;
  }
  UI.showSaleDone = (kind, d) => {
    const Body = ({ mid }) => html`<div class="workspace-complete"><div class="workspace-complete-icon">${I('check',32)}</div><h2>Продажа сохранена</h2><span>${d.no}</span><strong>${money(d.total)} <small>сом</small></strong>${d.cp ? html`<b>${E.cpName(d.cp)}</b>` : null}${d.total-d.paid > 0 ? html`<div class="workspace-total-line"><span>В долг</span><b>${money(d.total-d.paid)} сом</b></div>` : null}${d.pending ? html`<${Status} text="Ждёт отправки" tone="warn" />` : null}<div class="workspace-complete-actions"><button class="btn" onClick=${() => UI.workspacePrint(E.ref(d))}>${I('printer')}Накладная</button><button class="btn pri" onClick=${() => { UI.close(mid); UI.kassaStart('sale'); }}>Новая продажа</button><button class="btn" onClick=${() => { UI.close(mid); UI.go('kassaHome'); }}>На главную</button></div></div>`;
    return form('Готово', Body);
  };
  S.kassaDocView = ({ t, id }) => {
    const ref = {t,id}, data = docData(ref);
    if (!data) return html`<${Page} title="Документ не найден"><${Empty} text="Документ не найден" /><//>`;
    const d = data.d, sale = t === 'sale', order = t === 'order', financial = !['sale','order','ret'].includes(t);
    const stage = order ? P.orderStage(d) : null;
    const returned = sale ? E.S.returns.filter((r) => r.saleId === id && r.status === 'posted') : [];
    const canReturn = sale && d.status === 'posted' && !d.pending && d.lines.some((l,i) => E.returnedOf(id,i).qty < l.qty);
    const cancelSale = (reason, correct) => {
      if (correct) { const draft = P.correctSale(id,reason); UI.go('kassaSale',{id:draft.id}); }
      else { E.cancelSale(id); d.cancelReason = reason; E.changed(); }
    };
    const actions = html`${financial && d.status === 'posted' && (t === 'debt' && !d.sourceSaleId || t === 'off' || t === 'pay' && !d.src) ? html`<button class="btn danger" onClick=${() => form('Отменить операцию',ConfirmReason,{label:'Отменить операцию',onConfirm:(reason) => P.cancelFinancial(ref,reason)})}>Отменить</button>` : null}${t === 'pay' && d.src ? html`<button class="btn" onClick=${() => openDoc(d.src)}>Исходный документ</button>` : null}${sale ? html`<button class="btn" onClick=${() => run(() => E.copyDoc(ref),(copy) => UI.go('kassaSale',{id:copy.id}))}>Повторить</button>` : null}${!financial ? html`<button class="btn" onClick=${() => UI.workspacePrint(ref)}>${I('printer')}Накладная</button>` : null}${order ? html`<button class="btn" onClick=${() => UI.workspacePrint(ref,true)}>Лист сборки</button>` : null}${sale && d.status === 'posted' ? html`<button class="btn" disabled=${!canReturn} onClick=${() => startReturn(d)}>Возврат</button><button class="btn" onClick=${() => form('Исправить продажу', ConfirmReason, {label:'Исправить',onConfirm:(reason) => cancelSale(reason,true)})}>Исправить</button><button class="btn danger" onClick=${() => form('Отменить продажу', ConfirmReason, {label:'Отменить продажу',onConfirm:(reason) => cancelSale(reason,false)})}>Отменить</button>` : null}${sale && d.pending ? html`<button class="btn" onClick=${() => run(() => P.fixPendingSale(id),(draft) => UI.go('kassaSale',{id:draft.id}))}>Исправить отправку</button>` : null}`;
    return html`<${Page} title=${`${E.TITLE[t]} ${d.no}`} back="Просмотр" onBack=${() => go(t === 'ret' ? 'returns' : t === 'order' ? 'orders' : financial ? 'payments' : 'sales')} actions=${actions}><div class="workspace-document-meta"><button class="workspace-person-link" disabled=${!d.cp} onClick=${() => UI.go('kassaPerson',{id:d.cp})}>${I('users')}<b>${E.cpName(d.cp)}</b></button><span>${U.fmtDT(d.postedAt || d.at)}</span><${Status} text=${order ? ({new:'Новый',working:'В работе',shipped:'Отправлен',done:'Завершён',cancelled:'Отменён'}[stage]) : sale ? saleStatus(d) : d.status === 'cancelled' ? 'Отменён' : 'Сохранено'} tone=${d.status === 'cancelled' ? '' : d.pending ? 'warn' : 'ok'} /></div>${d.cancelReason ? html`<div class="workspace-cancel-reason">${d.cancelReason}</div>` : null}${data.groups.length ? html`<${DocumentLines} data=${data} /><div class="workspace-doc-totals"><div class="workspace-total-line"><span>Итого</span><b>${money(data.total)} сом</b></div>${sale ? html`<div><span>Оплачено при продаже</span><b>${money(d.paid)} сом</b></div>${P.saleDebt(d) > 0 ? html`<div class="workspace-debt-recv"><span>Долг сейчас</span><b>${money(P.saleDebt(d))} сом</b></div>` : null}${returned.length ? html`<div><span>Возвращено</span><b>${money(returned.reduce((n,r) => n+r.amount,0))} сом</b></div>` : null}` : t === 'ret' ? html`<div><span>Уменьшение долга</span><b>${money(d.toDebt)} сом</b></div><div><span>Выдано деньгами</span><b>${money(d.refundNow)} сом</b></div>` : null}</div>` : html`<div class="workspace-financial-detail"><strong>${money(d.amount)} <small>сом</small></strong><span>${t === 'pay' ? d.dir === 'in' ? 'Получено' : 'Выдано' : t === 'debt' ? d.dir === 'recv' ? 'Нам должны' : 'Мы должны' : 'Взаимозачёт'}</span>${t === 'pay' ? html`<span>${methods(d)}</span>` : null}</div>`}${(sale || order) ? html`<${NeighborSummary} doc=${d} />` : null}${d.comment ? html`<div class="workspace-document-comment">${d.comment}</div>` : null}${order && !['done','cancelled'].includes(stage) ? html`<${OrderActions} order=${d} />` : null}${data.source ? html`<button class="btn" onClick=${() => openDoc(E.ref(data.source))}>Чек ${data.source.no}</button>` : null}${returned.length ? html`<div class="workspace-linked-docs">${returned.map((r) => html`<button class="btn" onClick=${() => openDoc(E.ref(r))}>${r.no} · ${money(r.amount)} сом</button>`)}</div>` : null}<//>`;
  };

  function ReturnEditor({ mid, returnId }) {
    const r = E.doc({t:'ret',id:returnId}), sale = E.doc({t:'sale',id:r.saleId});
    const [, tick] = useState(0), [error,setError] = useState(''), [method,setMethod] = useState('cash'), [manual,setManual] = useState(null), [comment,setComment] = useState('');
    const calc = E.returnCalc(r), refund = manual === null ? calc.refund : manual;
    const groups = E.documentProductGroups(sale);
    r.refundNow = refund;
    const valid = !E.validateReturn(r).errs.length;
    const cancel = () => { E.deleteDraft(E.ref(r)); UI.close(mid); };
    return html`<div class="workspace-return"><div class="workspace-document-meta"><b>${sale.no}</b><span>${E.cpName(sale.cp)}</span></div><div class="workspace-table-wrap"><table class="workspace-table"><thead><tr><th>Размер</th><th class="num">Продано</th><th class="num">Можно вернуть</th><th class="num">Возврат</th></tr></thead>${groups.map((g) => html`<tbody key=${g.key}><tr class="workspace-product-heading"><th colspan="4">${g.name}</th></tr>${g.items.map((item) => { const x = calc.lines[item.index]; return html`<tr><td>${item.product.variantName || 'Основной'}</td><td class="num">${U.qty(item.line.qty)}</td><td class="num">${U.qty(x.can)}</td><td class="num"><${UI.Num} cls="in workspace-return-qty" aria-label=${`Вернуть ${g.name}, размер ${item.product.variantName || 'Основной'}`} disabled=${x.can <= 0} value=${r.lines[item.index].qty} bad=${!U.isNum(r.lines[item.index].qty) || r.lines[item.index].qty < 0 || r.lines[item.index].qty > x.can} onChange=${(value) => { r.lines[item.index].qty = value; setError(''); tick((v) => v+1); }} /></td></tr>`; })}</tbody>`)}</table></div><div class="workspace-doc-totals"><div class="workspace-total-line"><span>Итого возврат</span><b>${money(calc.amount)} сом</b></div>${calc.toDebt > 0 ? html`<div><span>Уменьшит долг</span><b>${money(calc.toDebt)} сом</b></div>` : null}${calc.refund > 0 ? html`<div><span>К выдаче</span><b>${money(calc.refund)} сом</b></div><label class="workspace-inline-field">Выдать сейчас<${UI.Num} cls="in" aria-label="Выдать сейчас" value=${refund} onChange=${setManual} /></label><${Tabs} value=${method} onChange=${setMethod} items=${[{k:'cash',t:'Наличные'},{k:'mbank',t:'МБанк'}]} />${refund < calc.refund ? html`<div class="workspace-debt-pay"><span>Останемся должны</span><b>${money(calc.refund-refund)} сом</b></div>` : null}` : null}</div><label class="workspace-reason-label">Причина<textarea class="in" aria-label="Причина возврата" value=${comment} onInput=${(e) => setComment(e.target.value)} /></label>${error ? html`<p class="workspace-error" role="alert">${error}</p>` : null}<div class="workspace-form-actions"><button class="btn" onClick=${cancel}>Отмена</button><button class="btn pri" disabled=${!valid} onClick=${() => { try { r.refundNow=refund; r.payMethods=refund>0?{[method]:refund}:{}; r.comment=comment; E.postReturn(r.id); UI.close(mid); openDoc(E.ref(r)); } catch (x) { setError(x.message); } }}>Оформить возврат</button></div></div>`;
  }
  function startReturn(sale) {
    if (sale.pending) { UI.toast('Сначала отправьте продажу', 'err'); return; }
    run(() => E.newReturn(sale.id), (r) => UI.modal({ title:'Возврат', size:'workspace wide', sticky:true, onClose:() => { const current=E.doc(E.ref(r)); if(current?.status==='draft') E.deleteDraft(E.ref(r)); }, body:(mid) => html`<${ReturnEditor} mid=${mid} returnId=${r.id} />` }));
  }

  S.kassaPerson = ({ id }) => {
    const person = E.cp(id), [tab,setTab] = useState('history');
    if (!person) return html`<${Page} title="Человек не найден"><${Empty} /><//>`;
    const balance = E.balance(id);
    const history = [];
    [['sales','sale'],['returns','ret'],['payments','pay'],['debtNotes','debt'],['offsets','off'],['orders','order']].forEach(([collection,t]) => (E.S[collection] || []).filter((d) => d.cp === id && (d.status !== 'draft' || t === 'order' && d.lines.length)).forEach((d) => history.push({id:t+':'+d.id,doc:d,ref:{t,id:d.id},at:d.postedAt || d.at,amount:t === 'sale' ? d.total : t === 'order' ? E.calcLines(d).total : d.amount})));
    const debts = E.debtsOf(id).filter((d) => E.debtRem(d)>0);
    const offset = async () => { const amount=Math.min(balance.recv,balance.pay); if(await UI.confirm(`Зачесть ${money(amount)} сом встречных долгов?`,{title:'Взаимозачёт',ok:'Зачесть'})) run(() => E.applyOffset(id)); };
    return html`<${Page} title=${person.name} back="Люди" onBack=${() => go('people')} actions=${html`<button class="btn" onClick=${() => form('Изменить человека',PersonEditor,{id})}>${I('edit')}Изменить</button>`}><div class="workspace-document-meta"><span>${person.phone || 'Телефон не указан'}</span>${person.note ? html`<span>${person.note}</span>` : null}</div><div class="workspace-balances"><button disabled=${!balance.recv} onClick=${() => form('Принять оплату долга',DebtPayment,{cp:id,dir:'recv'})}><span>Нам должны</span><b>${money(balance.recv)} сом</b></button><button disabled=${!balance.pay} onClick=${() => form('Выдать деньги',DebtPayment,{cp:id,dir:'pay'})}><span>Мы должны</span><b>${money(balance.pay)} сом</b></button></div><div class="workspace-toolbar"><button class="btn pri" disabled=${!balance.recv} onClick=${() => form('Принять оплату долга',DebtPayment,{cp:id,dir:'recv'})}>${I('wallet')}Принять оплату</button><button class="btn" disabled=${!balance.pay} onClick=${() => form('Выдать деньги',DebtPayment,{cp:id,dir:'pay'})}>Выдать деньги</button><button class="btn" onClick=${() => form('Записать долг',DebtEditor,{cp:id})}>Записать долг</button>${balance.recv && balance.pay ? html`<button class="btn" onClick=${offset}>Взаимозачёт</button>` : null}<span class="workspace-toolbar-sp"></span><button class="btn" onClick=${() => UI.kassaStart('sale',id)}>Продажа</button><button class="btn" onClick=${() => UI.kassaStart('order',id)}>Заказ</button></div><${Tabs} value=${tab} onChange=${setTab} items=${[{k:'history',t:'История'},{k:'debts',t:'Долги'}]} />${tab === 'history' ? html`<${Grid} head=${['Операция','Документ','Дата','Сумма, сом','Статус']} rows=${newest(history)} numeric=${[3]} onOpen=${(r) => openDoc(r.ref)} cells=${(r) => [E.TITLE[r.ref.t],r.doc.no,U.fmtDT(r.at),money(r.amount),html`<${Status} text=${r.doc.status === 'cancelled' ? 'Отменён' : r.doc.pending ? 'Ждёт отправки' : 'Сохранено'} />`]} empty="Операций пока нет" />` : html`<${Grid} head=${['Направление','Основание','Дата','Сумма долга, сом','Осталось, сом']} rows=${debts} numeric=${[3,4]} onOpen=${(d) => openDoc(d.ref)} cells=${(d) => [d.dir === 'recv' ? 'Нам должны' : 'Мы должны',E.refNo(d.ref),U.fmtDate(d.at),money(d.amount),html`<b>${money(E.debtRem(d))}</b>`]} empty="Долгов нет" />`}<//>`;
  };

  const stageLabel = (o) => ({new:'Новый',working:'В работе',shipped:'Отправлен',done:'Завершён',cancelled:'Отменён'}[P.orderStage(o)]);
  function move(o,stage) {
    run(() => P.moveOrder(o,stage),(sale) => { if(stage === 'done' && sale) { UI.go('kassaSale',{id:sale.id}); UI.kassaPay(sale); } });
  }
  function OrderActions({ order }) {
    const stage=P.orderStage(order);
    return html`<div class="workspace-order-actions">${stage === 'new' ? html`<button class="btn" onClick=${() => UI.go('kassaOrder',{id:order.id})}>${I('edit')}Редактировать</button><button class="btn pri" onClick=${() => move(order,'working')}>В работу</button>` : html`<button class="btn" onClick=${() => move(order,stage === 'shipped' ? 'working' : 'new')}>${stage === 'shipped' ? 'В работу' : 'В новые'}</button>${stage !== 'shipped' ? html`<button class="btn" onClick=${() => move(order,'shipped')}>Отправить</button>` : null}<button class="btn pri" onClick=${() => move(order,'done')}>Принять оплату</button>`}<button class="btn danger" onClick=${() => form('Отменить заказ',ConfirmReason,{label:'Отменить заказ',onConfirm:(reason) => { E.setOrderStatus(order.id,'cancelled'); order.cancelReason=reason; P.track('order-cancel',E.ref(order)); E.changed(); }})}>Отменить</button></div>`;
  }
  function OrderBoard({ orders }) {
    const [archive,setArchive] = useState(false), [over,setOver] = useState('');
    const cancelled=orders.filter((o) => o.status === 'cancelled');
    return html`<div><div class="workspace-order-board">${P.orderStages.map((stage) => { const rows=newest(orders.filter((o) => P.orderStage(o)===stage.k)); return html`<section class="workspace-order-column ${over===stage.k?'over':''}" key=${stage.k} onDragOver=${(e) => { e.preventDefault(); setOver(stage.k); }} onDragLeave=${() => setOver('')} onDrop=${(e) => { e.preventDefault(); setOver(''); const o=E.doc({t:'order',id:e.dataTransfer.getData('text/plain')}); if(o) move(o,stage.k); }}><header><h2>${stage.t}</h2><span>${rows.length}</span></header><div>${rows.map((o) => { const groups=E.documentProductGroups(o); return html`<article class="workspace-order-card" key=${o.id} draggable=${stage.k!=='done'} onDragStart=${(e) => e.dataTransfer.setData('text/plain',o.id)}><button type="button" class="workspace-order-open" onClick=${() => openDoc(E.ref(o))}><div class="workspace-order-number"><span>${o.no}</span><span>${U.fmtDate(o.at)}</span></div><b>${E.cpName(o.cp)}</b><div class="workspace-order-products">${groups.slice(0,2).map((g) => html`<div><strong>${g.name}</strong><span>${g.items.map((item) => `${item.product.variantName || 'Основной'} × ${U.qty(item.line.qty)}`).join(' · ')}</span></div>`)}${groups.length>2?html`<span>Ещё ${groups.length-2}</span>`:null}</div><strong class="workspace-order-total">${money(E.calcLines(o).total)} сом</strong></button>${stage.k!=='done' ? html`<div class="workspace-order-card-actions"><button class="btn" onClick=${() => move(o,stage.k==='new'?'working':stage.k==='working'?'shipped':'done')}>${stage.k==='new'?'В работу':stage.k==='working'?'Отправить':'Принять оплату'}</button></div>` : null}</article>`; })}${!rows.length ? html`<${Empty} text="Нет заказов" />` : null}</div></section>`; })}</div>${cancelled.length ? html`<button class="btn workspace-order-archive" onClick=${() => setArchive(!archive)}>Отменённые · ${cancelled.length}</button>${archive ? html`<${Grid} head=${['Заказ','Покупатель','Дата','Сумма, сом']} rows=${cancelled} numeric=${[3]} onOpen=${(o) => openDoc(E.ref(o))} cells=${(o) => [o.no,E.cpName(o.cp),U.fmtDate(o.at),money(E.calcLines(o).total)]} />` : null}` : null}</div>`;
  }
  UI.saveOrderDialog = (order) => {
    const Body=({mid}) => {
      const [comment,setComment]=useState(order.comment || ''),[working,setWorking]=useState(false),[error,setError]=useState('');
      return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { const validation=E.validateOrder(order,false); if(validation.errs.length) throw new E.AccErr(validation.errs[0].msg); order.comment=comment; order.updatedRevision=(order.updatedRevision||0)+1; if(working && order.status==='draft') P.moveOrder(order,'working'); E.orderSaved(order.id); E.changed(); UI.close(mid); openDoc(E.ref(order)); } catch(x) { setError(x.message); } }}><div class="workspace-form-product"><b>${E.cpName(order.cp)}</b><span>${order.no}</span></div><div class="workspace-total-line"><span>Итого</span><b>${money(E.calcLines(order).total)} сом</b></div><label>Комментарий<textarea class="in" value=${comment} onInput=${(e) => setComment(e.target.value)} /></label><label class="workspace-checkbox"><input type="checkbox" checked=${working} onChange=${(e) => setWorking(e.target.checked)} />Передать в работу</label>${error?html`<p class="workspace-error" role="alert">${error}</p>`:null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Назад</button><button type="submit" class="btn pri">Сохранить заказ</button></div></form>`;
    }; return form('Сохранить заказ',Body);
  };

  function ProductEditor({ mid, group }) {
    const all = group ? E.productGroups(E.S.products).find((g) => g.key===group.key) : null;
    const [name,setName]=useState(all?.name || ''),[photo,setPhoto]=useState(all?.photo || ''),[unit,setUnit]=useState(all?.products[0]?.unit || 'шт'),[rows,setRows]=useState(all?.products.map((p) => ({id:p.id,size:p.variantName,retail:p.retailPrice,wholesale:p.wholesalePrice,active:p.active})) || [{id:null,size:'',retail:0,wholesale:0,active:true}]),[error,setError]=useState('');
    const update=(index,key,value) => setRows((prev) => prev.map((r,i) => i===index?{...r,[key]:value}:r));
    const save=() => {
      const sizes=rows.filter((r) => r.active);
      if(!name.trim() || (!sizes.length && !all) || rows.some((r) => !r.size.trim() || !U.isNum(r.retail) || r.retail<0 || !U.isNum(r.wholesale) || r.wholesale<0)) throw new E.AccErr('Укажите название, размеры и корректные цены');
      if(new Set(sizes.map((r) => U.norm(r.size))).size!==sizes.length) throw new E.AccErr('Размеры не должны повторяться');
      const productKey=all?.products[0]?.externalProductId || `ui-${Date.now()}`;
      E.tx(() => rows.forEach((row,index) => { const old=row.id?E.product(row.id):null; E.saveProduct({name,photo,unit,variantName:row.size,retailPrice:row.retail,wholesalePrice:row.wholesale,purchasePrice:0,category:old?.category || '',active:row.active,externalProductId:productKey,externalSizeId:old?.externalSizeId || `${productKey}-${index}-${Date.now()}`},row.id || undefined); }));
      UI.close(mid); UI.go('kassaCatalog');
    };
    return html`<form class="workspace-form" onSubmit=${(e) => { e.preventDefault(); try { save(); } catch(x) { setError(x.message); } }}><label>Название<input class="in" aria-label="Название товара" value=${name} autofocus onInput=${(e) => setName(e.target.value)} /></label><div class="workspace-product-fields"><label>Фото<input class="in" aria-label="Ссылка на фото" type="url" value=${photo} onInput=${(e) => setPhoto(e.target.value)} /></label><label>Единица<select class="in" value=${unit} onChange=${(e) => setUnit(e.target.value)}>${E.UNITS.map((u) => html`<option value=${u}>${u}</option>`)}</select></label></div><div class="workspace-table-wrap"><table class="workspace-table workspace-product-editor"><thead><tr><th>Размер</th><th>Розница</th><th>Опт</th><th>Активен</th></tr></thead><tbody>${rows.map((row,index) => html`<tr key=${row.id || index}><td><input class="in" aria-label=${`Размер ${index+1}`} value=${row.size} onInput=${(e) => update(index,'size',e.target.value)} /></td><td><${UI.Num} cls="in" aria-label=${`Розничная цена ${index+1}`} value=${row.retail} onChange=${(v) => update(index,'retail',v)} /></td><td><${UI.Num} cls="in" aria-label=${`Оптовая цена ${index+1}`} value=${row.wholesale} onChange=${(v) => update(index,'wholesale',v)} /></td><td><input type="checkbox" aria-label=${`Активен размер ${index+1}`} checked=${row.active} onChange=${(e) => update(index,'active',e.target.checked)} /></td></tr>`)}</tbody></table></div><button type="button" class="btn workspace-add-size" onClick=${() => setRows((prev) => [...prev,{id:null,size:'',retail:0,wholesale:0,active:true}])}>${I('plus')}Размер</button>${error?html`<p class="workspace-error" role="alert">${error}</p>`:null}<div class="workspace-form-actions"><button type="button" class="btn" onClick=${() => UI.close(mid)}>Отмена</button><button type="submit" class="btn pri">Сохранить</button></div></form>`;
  }
  S.kassaCatalog = () => {
    const [q,setQ]=useState(''),[archive,setArchive]=useState(false),[busy,setBusy]=useState(false);
    const groups=E.productGroups(E.S.products.filter((p) => archive?!p.active:p.active)).filter((g) => U.match(q,g.name,...g.products.map((p)=>p.variantName)));
    return html`<${Page} title="Каталог" actions=${html`<button class="btn" disabled=${busy} onClick=${async () => { setBusy(true); try { const count=await P.refreshCatalog(); UI.toast(`Каталог обновлён: ${count} размеров`,'ok'); } catch(x) { UI.toast(x.message,'err'); } finally { setBusy(false); } }}>${I('refresh-cw')}${busy?'Обновление…':'Обновить'}</button><button class="btn pri" onClick=${() => form('Новый товар',ProductEditor,{},'workspace wide')}>${I('plus')}Новый товар</button>`}><div class="workspace-toolbar"><${Search} value=${q} onChange=${setQ} placeholder="Товар или размер" /><label class="workspace-checkbox"><input type="checkbox" checked=${archive} onChange=${(e) => setArchive(e.target.checked)} />Архив</label></div><${Grid} head=${['Товар','Размеров','Цена, сом']} rows=${groups.map((g) => ({...g,id:g.key}))} numeric=${[1,2]} onOpen=${(g) => form('Товар',ProductEditor,{group:g},'workspace wide')} cells=${(g) => { const prices=g.products.map((p)=>p.retailPrice),min=Math.min(...prices),max=Math.max(...prices); return [html`<div class="workspace-catalog-name">${UI.productPhoto(g.products.find((p)=>p.photo)||g.products[0],48)}<b>${g.name}</b></div>`,g.products.length,min===max?money(min):`${money(min)}–${money(max)}`]; }} empty="Товаров не найдено" /><//>`;
  };

  function Transport({ mid }) {
    const [all,setAll]=useState(false),[,tick]=useState(0);
    const jobs=[...P.jobs].reverse().filter((j)=>all || ['pending','error'].includes(j.state));
    const change=(fn)=>{fn();tick((n)=>n+1);};
    return html`<div class="workspace-transport"><div class="workspace-transport-controls"><button class="btn ${P.online?'pri':''}" onClick=${()=>change(()=>P.setOnline(true))}>Связь включена</button><button class="btn ${!P.online?'pri':''}" onClick=${()=>change(()=>P.setOnline(false))}>Нет связи</button></div><label class="workspace-checkbox"><input type="checkbox" checked=${P.failNext} onChange=${(e)=>change(()=>{P.failNext=e.target.checked;})} />Следующая отправка с ошибкой</label><label class="workspace-checkbox"><input type="checkbox" checked=${all} onChange=${(e)=>setAll(e.target.checked)} />Показать отправленные</label><div class="workspace-job-list">${jobs.map((job)=>html`<article class="workspace-job" key=${job.id}><div><b>${job.title}</b><${Status} text=${{pending:'В очереди',error:'Ошибка',sent:'Отправлено',cancelled:'Отменено'}[job.state]} tone=${job.state==='error'?'warn':''} /></div>${job.error?html`<p class="workspace-error">${job.error}</p>`:null}<small>Попыток: ${job.attempts}</small><div><button class="btn" onClick=${()=>{UI.close(mid);openDoc(job.ref);}}>Открыть</button>${['pending','error'].includes(job.state)?html`<button class="btn pri" disabled=${!P.online} onClick=${()=>run(()=>P.retry(job.id))}>Повторить</button>`:null}</div></article>`)}${!jobs.length?html`<${Empty} text="Неотправленных операций нет" />`:null}</div><div class="workspace-form-actions"><button class="btn danger" onClick=${async()=>{if(await UI.confirm('Сбросить только тестовые продажи, заказы и долги? Рабочие данные не изменятся.',{title:'Сброс тестовых операций',ok:'Сбросить',danger:true})){P.reset();UI.close(mid);UI.go('kassaHome');}}}>Сбросить тестовые данные</button></div></div>`;
  }
})();
